 public void update(byte[] input,int offset,int length){need(input!=null&&offset>=0&&length>=0&&offset<=input.length-length&&total<=Long.MAX_VALUE/8-length,"ATOM_SHA_INPUT");while(length>0){int n=Math.min(length,64-used);System.arraycopy(input,offset,block,used,n);used+=n;total+=n;offset+=n;length-=n;if(used==64){compress();used=0;Arrays.fill(block,(byte)0);}}}
 public byte[] checkpoint(){ByteBuffer out=ByteBuffer.allocate(111);out.putInt(0x53434832).putShort((short)1).putLong(total).put((byte)used);for(int x:h)out.putInt(x);out.put(block,0,used);for(int i=used;i<64;i++)out.put((byte)0);return out.array();}
 public static ResumableSha256CP12 restore(byte[] bytes,long expectedCount){need(bytes!=null&&bytes.length==111,"ATOM_SHA_STATE_LENGTH");ByteBuffer b=ByteBuffer.wrap(bytes);need(b.getInt()==0x53434832&&b.getShort()==1,"ATOM_SHA_STATE_VERSION");long total=b.getLong();int used=b.get()&255;need(total==expectedCount&&total>=0&&total<=Long.MAX_VALUE/8&&used==total%64,"ATOM_SHA_STATE_COUNT");int[] h=new int[8];for(int i=0;i<8;i++)h[i]=b.getInt();byte[] block=new byte[64];b.get(block);for(int i=used;i<64;i++)need(block[i]==0,"ATOM_SHA_STATE_PADDING");return new ResumableSha256CP12(h,total,used,block);}
 public String digestHex(){ResumableSha256CP12 copy=restore(checkpoint(),total);long bits=total*8;int padding=used<56?56-used:120-used;byte[] end=new byte[padding+8];end[0]=(byte)128;ByteBuffer.wrap(end,end.length-8,8).putLong(bits);copy.update(end,0,end.length);StringBuilder result=new StringBuilder(64);for(int x:copy.h)for(int s=28;s>=0;s-=4)result.append(Character.forDigit((x>>>s)&15,16));return result.toString();}
 private void compress(){int[] w=words;for(int i=0;i<16;i++){int j=i*4;w[i]=(block[j]&255)<<24|(block[j+1]&255)<<16|(block[j+2]&255)<<8|(block[j+3]&255);}for(int i=16;i<64;i++){int x=w[i-15],y=w[i-2],a=Integer.rotateRight(x,7)^Integer.rotateRight(x,18)^(x>>>3),b=Integer.rotateRight(y,17)^Integer.rotateRight(y,19)^(y>>>10);w[i]=w[i-16]+a+w[i-7]+b;}int a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],v=h[7];for(int i=0;i<64;i++){int s1=Integer.rotateRight(e,6)^Integer.rotateRight(e,11)^Integer.rotateRight(e,25),ch=(e&f)^(~e&g),t1=v+s1+ch+K[i]+w[i],s0=Integer.rotateRight(a,2)^Integer.rotateRight(a,13)^Integer.rotateRight(a,22),maj=(a&b)^(a&c)^(b&c),t2=s0+maj;v=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;}h[0]+=a;h[1]+=b;h[2]+=c;h[3]+=d;h[4]+=e;h[5]+=f;h[6]+=g;h[7]+=v;}
